<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Smart Image Finder</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,'Segoe UI',sans-serif;color:#18283d;background:#f4f6fa}*{box-sizing:border-box}body{margin:0}button,input{font:inherit}button{cursor:pointer}header{background:#12263e;color:white;padding:22px max(16px,calc((100vw - 1120px)/2))}header strong{font-size:21px}header small{display:block;color:#c9d5e3;margin-top:5px}.wrap{max-width:1120px;margin:0 auto;padding:22px 16px 48px}.panel{background:white;border-radius:18px;padding:clamp(16px,3vw,28px);box-shadow:0 6px 24px #162b4210}h1{font-size:clamp(19px,3vw,24px);margin:0 0 8px}h2{font-size:20px;margin:26px 0 14px}.sub{color:#657589;font-size:14px;line-height:1.5;margin:0 0 20px}.tools{display:flex;gap:10px;flex-wrap:wrap}.btn{border:0;border-radius:11px;background:#ffa400;color:#17283f;font-weight:750;padding:13px 17px;min-height:45px}.btn.alt{background:#edf2f7}.btn:disabled{opacity:.55;cursor:wait}.drop{border:1.5px dashed #afc2d6;border-radius:15px;padding:18px;margin-top:16px;text-align:center;background:#fafcff;min-height:120px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px}.drop.drag{border-color:#ffa400;background:#fff8e8}.thumb{max-width:100%;max-height:240px;border-radius:12px;object-fit:contain}.muted{font-size:13px;color:#64758b}.file-name{word-break:break-all;font-size:13px;color:#34465d}.camera-box{margin-top:14px;display:none;max-width:540px}.camera-box.open{display:block}video{width:100%;border-radius:12px;background:#0d1729;max-height:350px;object-fit:contain}.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:18px}.status{font-size:13px;color:#586d84}.notice{font-size:13px;padding:12px 15px;background:#eaf1f8;border-radius:10px;margin-bottom:17px;line-height:1.5}.results{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:14px}.item{min-width:0;overflow:hidden;background:white;border-radius:14px;box-shadow:0 3px 16px #233b5714}.item img{width:100%;height:175px;object-fit:contain;background:#fff;padding:10px}.info{border-top:1px solid #e9eef5;padding:12px}.filename{font-weight:750;overflow-wrap:anywhere;font-size:14px}.meta{color:#69798c;font-size:12px;margin:7px 0;overflow-wrap:anywhere}.score{font-weight:750;color:#17744a;font-size:13px;margin:7px 0}.score.low{color:#a46815}.item img{cursor:zoom-in}.item img:focus{outline:3px solid #ffa400}.product-name{font-size:13px;font-weight:650;line-height:1.4;margin:6px 0}.product-price{font-size:15px;font-weight:800;color:#0a6843;margin:5px 0}.product-source{font-size:11px;color:#64748b}.modal{position:fixed;inset:0;background:#071322dc;display:flex;align-items:center;justify-content:center;z-index:9999;padding:16px}.modal-panel{background:white;max-width:950px;width:100%;max-height:95vh;border-radius:16px;display:flex;flex-direction:column;overflow:hidden}.modal-head{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid #ddd}.modal-head strong{overflow-wrap:anywhere;font-size:14px}.modal-close{border:0;background:#e9eef5;border-radius:8px;padding:8px 12px;cursor:pointer;font-size:20px}.modal-image{max-width:100%;max-height:calc(95vh - 110px);object-fit:contain;margin:auto;padding:10px}.error-banner{font-size:13px;color:#873d15;background:#fff1e4;padding:11px;border-radius:9px;margin-bottom:10px}.message{padding:16px;background:white;border-radius:12px;color:#4e6175}.hint{font-size:13px;color:#986b16;background:#fff6df;border-radius:10px;padding:12px 14px;margin-bottom:15px;line-height:1.5}[hidden]{display:none!important}@media(max-width:560px){header{padding:15px 16px}header strong{font-size:18px}.wrap{padding:13px 10px 35px}.panel{border-radius:13px}.tools{display:grid;grid-template-columns:1fr 1fr}.tools .btn{padding:12px 8px;font-size:13px}.actions .btn{width:100%}.results{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.item img{height:145px;padding:6px}.info{padding:9px}.filename{font-size:12px}.meta{font-size:11px}.score{font-size:12px}h2{font-size:18px;margin:22px 0 12px}}@media(max-width:340px){.results{grid-template-columns:1fr}}

.site-nav{display:flex;gap:8px;flex-wrap:wrap}.site-nav a{display:inline-flex;align-items:center;padding:10px 14px;border:1px solid #ffffff35;border-radius:10px;color:#fff;text-decoration:none;font-weight:600;font-size:13px}.site-nav a.active{background:#ffa400;color:#172c45;border-color:#ffa400}.source-note{font-size:13px;color:#536b83;margin:0 0 16px}@media(max-width:560px){header{display:flex;gap:12px;flex-wrap:wrap;justify-content:space-between}.site-nav{width:100%}.site-nav a{flex:1;justify-content:center}}
</style></head>
<body><header><div><strong>📷 Smart Image Finder</strong><small style="display:block;margin-top:4px">Cari produk berdasarkan foto</small></div><nav class="site-nav"><a class="active" href="/">📷 Cari Foto</a><a href="/gallery">▦ Galeri Barang</a></nav></header>
<main class="wrap"><div class="notice">Indeks katalog Google Drive: <strong>{{ number_format($count) }}</strong> gambar. Foto katalog tidak disimpan permanen di Laravel.</div>
<section class="panel"><h1>Cari produk berdasarkan foto</h1><p class="sub">Ambil foto atau unggah gambar, lalu cari kecocokan tertinggi. Pencarian mencakup seluruh katalog INGCO dan WADFOW. Mode AI Multi-Crop secara otomatis membandingkan foto asli dan beberapa area fokus produk untuk menemukan 5 kandidat terdekat.</p>
<div class="tools"><button type="button" class="btn alt" id="uploadBtn">📁 Pilih gambar</button><button type="button" class="btn alt" id="cameraBtn">📸 Gunakan kamera</button></div>
<input type="file" id="file" accept="image/jpeg,image/png,image/webp,image/gif" hidden>
<div id="cameraBox" class="camera-box"><video id="camera" autoplay playsinline muted></video><div class="tools" style="margin-top:8px"><button type="button" class="btn" id="snap">Ambil foto</button><button type="button" class="btn alt" id="closeCam">Tutup kamera</button></div></div>
<div id="drop" class="drop"><div id="emptyPreview"><strong>Foto yang akan dicari</strong><div class="muted">JPG, PNG, WEBP, GIF • Maksimal 10 MB</div></div><img id="preview" class="thumb" alt="Foto pilihan" hidden><div id="selected" class="file-name" hidden></div></div>
<div class="actions"><button type="button" id="search" class="btn">🔎 Cari gambar mirip</button><span id="status" class="status" role="status" aria-live="polite"></span></div>
</section><h2>Hasil pencarian</h2><div id="dbError" class="error-banner" hidden></div><div id="hint" class="hint" hidden></div><div id="results" class="results"></div></main>
<script>
const file=document.getElementById('file'), preview=document.getElementById('preview'), selected=document.getElementById('selected'), statusEl=document.getElementById('status'), results=document.getElementById('results'), hint=document.getElementById('hint'), cameraBox=document.getElementById('cameraBox'), video=document.getElementById('camera'), searchBtn=document.getElementById('search');
let current=null, stream=null, objectUrl=null;
function show(blob){if(objectUrl)URL.revokeObjectURL(objectUrl);current=blob;objectUrl=URL.createObjectURL(blob);preview.src=objectUrl;preview.hidden=false;selected.hidden=false;selected.textContent=blob.name||'Foto dari kamera';document.getElementById('emptyPreview').hidden=true;statusEl.textContent='Gambar siap dicari';results.replaceChildren();hint.hidden=true;}
function stopCam(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}video.srcObject=null;cameraBox.classList.remove('open');}
document.getElementById('uploadBtn').onclick=()=>file.click();file.onchange=()=>{const f=file.files[0];if(f){stopCam();show(f);}};
document.getElementById('cameraBtn').onclick=async()=>{stopCam();if(!navigator.mediaDevices?.getUserMedia){statusEl.textContent='Akses kamera memerlukan HTTPS atau localhost.';return;}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=stream;cameraBox.classList.add('open');await video.play();statusEl.textContent='Kamera siap';}catch(e){statusEl.textContent='Kamera tidak dapat dibuka: '+e.message;}};
document.getElementById('closeCam').onclick=stopCam;
document.getElementById('snap').onclick=()=>{if(!video.videoWidth){statusEl.textContent='Tunggu kamera siap';return;}const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(b=>{if(b){show(new File([b],'camera.jpg',{type:'image/jpeg'}));stopCam();}},'image/jpeg',.9);};
const drop=document.getElementById('drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag');};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');const f=e.dataTransfer.files[0];if(f&&f.type.startsWith('image/')){stopCam();show(f);}};
searchBtn.onclick=async()=>{if(!current){statusEl.textContent='Silakan pilih atau ambil foto terlebih dahulu.';return;}if(current.size>10*1024*1024){statusEl.textContent='Ukuran gambar maksimal 10 MB.';return;}searchBtn.disabled=true;statusEl.textContent='Membandingkan gambar...';results.replaceChildren();hint.hidden=true;document.getElementById('dbError').hidden=true;const data=new FormData();data.append('image',current,current.name||'photo.jpg');try{const response=await fetch('/search',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'},body:data});const obj=await response.json();if(!response.ok)throw Error(obj.message||'HTTP '+response.status);statusEl.textContent='AI membandingkan dengan '+obj.total+' gambar';if(!obj.results?.length){const m=document.createElement('div');m.className='message';m.textContent='Belum ada gambar dalam indeks. Jalankan php artisan images:sync-drive.';results.append(m);return;}hint.hidden=false;hint.textContent='AI Multi-Crop menampilkan '+obj.results.length+' kandidat teratas. Skor merupakan gabungan kemiripan embedding, bukan probabilitas kepastian produk. Periksa foto, kode dan nama barang.';const dbError=document.getElementById('dbError');const dbErrors=Object.keys(obj.database_errors||{});dbError.hidden=dbErrors.length===0;dbError.textContent=dbErrors.length?'Info database: '+dbErrors.join(', ')+' belum dapat diakses. Hasil visual tetap tersedia.':'';
for(const item of obj.results){
 const card=document.createElement('article');card.className='item';
 const img=document.createElement('img');img.src=item.thumbnail_url||item.url;img.loading='lazy';img.onerror=()=>{if(item.thumbnail_url && img.src!==new URL(item.original_url,location.href).href){img.onerror=null;img.src=item.original_url;}else{img.onerror=null;img.alt='Gambar tidak dapat dimuat: '+item.name;}};img.alt='Perbesar '+item.name;img.tabIndex=0;img.setAttribute('role','button');img.setAttribute('aria-label','Perbesar gambar '+item.name);
 img.onclick=()=>openImageModal(item.original_url||item.url,item.name,img,item.thumbnail_url||null);img.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openImageModal(item.original_url||item.url,item.name,img,item.thumbnail_url||null);}};
 const info=document.createElement('div');info.className='info';
 const name=document.createElement('div');name.className='filename';name.textContent=item.name;
 const code=document.createElement('div');code.className='meta';code.textContent='Item Code: '+(item.item_code||'-');
 const score=document.createElement('div');score.className='score';score.textContent=item.score+'% skor AI Multi-Crop (relatif)';
 const productName=document.createElement('div');productName.className='product-name';productName.textContent=item.product?.item_name||'Data barang tidak ditemukan di SQL Server';
 const price=document.createElement('div');price.className='product-price';price.textContent=item.product?.price==null?'Harga RETAIL: -':'Harga RETAIL: '+new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:2}).format(item.product.price);
 const source=document.createElement('div');source.className='product-source';source.textContent=item.product?'Sumber: '+item.product.database+' • '+item.product.price_level:'';
 info.append(name,code,score,productName,price,source);card.append(img,info);results.append(card);
}}catch(e){statusEl.textContent='Gagal mencari: '+e.message;}finally{searchBtn.disabled=false;}};
window.addEventListener('pagehide',()=>{stopCam();if(objectUrl)URL.revokeObjectURL(objectUrl);});
</script>
<div id="imageModal" class="modal" role="dialog" aria-modal="true" aria-label="Perbesar gambar produk" hidden>
  <div class="modal-panel">
    <div class="modal-head"><strong id="modalTitle"></strong><button type="button" class="modal-close" id="modalClose" aria-label="Tutup">×</button></div>
    <img id="modalImage" class="modal-image" alt="Preview gambar produk" />
  </div>
</div>
<script>
const imageModal=document.getElementById('imageModal'),modalImage=document.getElementById('modalImage'),modalTitle=document.getElementById('modalTitle'),modalClose=document.getElementById('modalClose');
let modalOpener=null;
let modalFallback=null;
modalImage.onerror=()=>{if(modalFallback && modalImage.src!==new URL(modalFallback,location.href).href){modalImage.src=modalFallback;modalFallback=null;modalTitle.textContent+=' (preview thumbnail; gambar asli tidak tersedia)';}else{modalImage.onerror=null;modalImage.removeAttribute('src');modalTitle.textContent+=' (gambar gagal dimuat)';}};
function closeImageModal(){imageModal.hidden=true;modalFallback=null;modalImage.removeAttribute('src');document.body.style.overflow='';if(modalOpener)modalOpener.focus();}
function openImageModal(url,title,opener,fallback=null){modalOpener=opener;modalFallback=fallback;modalTitle.textContent=title;modalImage.src=url;modalImage.alt=title;imageModal.hidden=false;document.body.style.overflow='hidden';modalClose.focus();}
modalClose.onclick=closeImageModal;
imageModal.onclick=e=>{if(e.target===imageModal)closeImageModal();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!imageModal.hidden)closeImageModal();});
</script></body></html>
